Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

typedef long long ll;
typedef vector<int> vi;

const int INF = 1000000007;

inline void read(int &x) { scanf("%d", &x); }
inline void read(int &a, int &b) { scanf("%d %d", &a, &b); }
inline void read(int &a, int &b, int &c) { scanf("%d %d %d", &a, &b, &c); }
inline void read(int &a, int &b, int &c, int &d) { scanf("%d %d %d %d", &a, &b, &c, &d); }

inline void readln(int &x) { scanf("%d\n", &x); }
inline void readln(int &a, int &b) { scanf("%d %d\n", &a, &b); }
inline void readln(int &a, int &b, int &c) { scanf("%d %d %d\n", &a, &b, &c); }
inline void readln(int &a, int &b, int &c, int &d) { scanf("%d %d %d %d\n", &a, &b, &c, &d); }

inline void writeln(int x) { printf("%d\n", x); }
inline void writeln(int a, int b) { printf("%d %d\n", a, b); }
inline void writeln(int a, int b, int c) { printf("%d %d %d\n", a, b, c); }
inline void writeln(int a, int b, int c, int d) { printf("%d %d %d %d\n", a, b, c, d); }

inline void write(int x) { printf("%d", x); }
inline void write(int a, int b) { printf("%d %d", a, b); }
inline void write(int a, int b, int c) { printf("%d %d %d", a, b, c); }
inline void write(int a, int b, int c, int d) { printf("%d %d %d %d", a, b, c, d); }

void read_vector(vi &v, int n) {
    int x;
    for (int i = 0; i < n; ++i) {
        read(x);
        v.push_back(x);
    }
}

void write_vector(const vi &v) {
    for (size_t i = 0; i < v.size(); ++i) {
        printf("%d%c", v[i], (i == v.size() - 1) ? '\n' : ' ');
    }
}

void solve() {
    int n, t;
    vi arr;
    read(n);
    read_vector(arr, n);
    sort(arr.begin(), arr.end());

    int left = 0, right = 0, max_len = 0;
    read(t);

    while (right < n) {
        while (right < n && arr[right] - arr[left] <= t) {
            ++right;
        }
        max_len = max(max_len, right - left);
        ++left;
    }

    writeln(max_len);
}

int main() {
    solve();
    return 0;
}
